    Node(int _val) : val(_val), prev(nullptr), next(nullptr) {}
    Node(int _val, Node* _prev, Node* _next) : val(_val), prev(_prev), next(_next) {}
};

class Solution {
public:
    std::vector<int> toArray(Node* node) {
        if (!node) return {};
        Node* curr = node;
        while (curr->prev) curr = curr->prev;
        std::vector<int> res;
        while (curr) {
            res.push_back(curr->val);
            curr = curr->next;
        }
        return res;
    }
