import java.util.*;

class Node {
    public int val;
    public Node prev;
    public Node next;
    public Node() {}
    public Node(int _val) { val = _val; }
    public Node(int _val, Node _prev, Node _next) { val = _val; prev = _prev; next = _next; }
}

class Solution {
    public int[] toArray(Node node) {
        if (node == null) return new int[0];
        Node curr = node;
        while (curr.prev != null) curr = curr.prev;
        List<Integer> list = new ArrayList<>();
        while (curr != null) {
            list.add(curr.val);
            curr = curr.next;
        }
        int[] res = new int[list.size()];
        for (int i = 0; i < list.size(); i++) res[i] = list.get(i);
        return res;
    }
}

var toArray = function(node) {
    if (!node) return [];
